// Lux API with real Go WASM integration
// This file provides a bridge between Cloudflare Workers and the Go WASM module

// Global WASM module cache
let wasmModule = null;
let goInstance = null;

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    try {
      if (path === "/api/health") {
        return handleHealth();
      } else if (path === "/api/extract") {
        return handleExtract(request);
      } else {
        return new Response(
          JSON.stringify({
            status: "error",
            message: "Endpoint not found",
          }),
          {
            status: 404,
            headers: { "Content-Type": "application/json" },
          },
        );
      }
    } catch (error) {
      return new Response(
        JSON.stringify({
          status: "error",
          message: "Internal server error",
          error: error.message,
        }),
        {
          status: 500,
          headers: { "Content-Type": "application/json" },
        },
      );
    }
  },
};

function handleHealth() {
  return new Response(
    JSON.stringify({
      status: "ok",
      service: "lux-api",
      version: "1.0.0",
      timestamp: new Date().toISOString(),
      wasm_loaded: wasmModule !== null,
      capabilities: [
        "YouTube video extraction",
        "Bilibili video extraction", 
        "TikTok video extraction",
        "General URL parsing",
        "Multiple format support",
        "Go WASM integration"
      ]
    }),
    {
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type",
      },
    },
  );
}

async function handleExtract(request) {
  const url = new URL(request.url);
  
  // Handle CORS preflight
  if (request.method === "OPTIONS") {
    return new Response(null, {
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type",
      },
    });
  }

  let videoURL;

  if (request.method === "GET") {
    videoURL = url.searchParams.get("url");
  } else if (request.method === "POST") {
    try {
      const body = await request.json();
      videoURL = body.url;
    } catch (error) {
      return new Response(
        JSON.stringify({
          status: "error",
          message: "Invalid JSON body",
        }),
        {
          status: 400,
          headers: { "Content-Type": "application/json" },
        },
      );
    }
  } else {
    return new Response(
      JSON.stringify({
        status: "error",
        message: "Method not allowed",
      }),
      {
        status: 405,
        headers: { "Content-Type": "application/json" },
      },
    );
  }

  if (!videoURL) {
    return new Response(
      JSON.stringify({
        status: "error",
        message: "URL parameter is required",
      }),
      {
        status: 400,
        headers: { "Content-Type": "application/json" },
      },
    );
  }

  // Validate URL
  try {
    new URL(videoURL);
  } catch (error) {
    return new Response(
      JSON.stringify({
        status: "error",
        message: "Invalid URL provided",
      }),
      {
        status: 400,
        headers: { "Content-Type": "application/json" },
      },
    );
  }

  // Try to use Go WASM if available, otherwise fall back to simulation
  try {
    const result = await extractWithLuxWasm(videoURL);
    return new Response(
      JSON.stringify({
        status: "success",
        data: result,
        method: "wasm",
      }),
      {
        headers: {
          "Content-Type": "application/json",
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type",
        },
      },
    );
  } catch (error) {
    console.log("WASM extraction failed, falling back to simulation:", error);
    
    // Fall back to simulation
    const extractedData = await simulateLuxExtraction(videoURL);
    return new Response(
      JSON.stringify({
        status: "success",
        data: extractedData,
        method: "simulation",
        note: "WASM module not available, using simulated data"
      }),
      {
        headers: {
          "Content-Type": "application/json",
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type",
        },
      },
    );
  }
}

// Try to extract using the Go WASM module
async function extractWithLuxWasm(videoURL) {
  if (!wasmModule) {
    await initializeWasmModule();
  }
  
  if (!wasmModule) {
    throw new Error("WASM module not available");
  }
  
  // Call the Go function through the WASM interface
  try {
    const result = await callGoFunction(videoURL);
    return JSON.parse(result);
  } catch (error) {
    throw new Error(`WASM execution failed: ${error.message}`);
  }
}

// Initialize the WASM module
async function initializeWasmModule() {
  try {
    // Try to load the WASM module
    const wasmResponse = await fetch("worker.wasm");
    if (!wasmResponse.ok) {
      throw new Error("WASM module not found");
    }
    
    const wasmBuffer = await wasmResponse.arrayBuffer();
    
    // Create a simple Go runtime for Cloudflare Workers
    const go = {
      importObject: {
        env: {
          // System call stubs
          exit: (code) => {
            console.log(`Go program exited with code: ${code}`);
          },
          abort: (msg, file, line, col) => {
            console.error(`Go abort: ${msg} at ${file}:${line}:${col}`);
          },
          // Memory management stubs
          memory: new WebAssembly.Memory({ initial: 17, maximum: 16384 }),
          table: new WebAssembly.Table({ initial: 1, maximum: 1, element: 'anyfunc' }),
          __indirect_function_table: new WebAssembly.Table({ initial: 0, maximum: 0, element: 'anyfunc' }),
        },
        go: {
          debug: (value) => {
            console.log("[Go Debug]", value);
          },
        },
      },
    };
    
    // Instantiate the WASM module
    const result = await WebAssembly.instantiate(wasmBuffer, go.importObject);
    wasmModule = result.instance;
    
    console.log("Go WASM module loaded successfully");
  } catch (error) {
    console.error("Failed to initialize WASM module:", error);
    wasmModule = null;
  }
}

// Call a Go function from WASM
async function callGoFunction(videoURL) {
  if (!wasmModule || !wasmModule.exports) {
    throw new Error("WASM module not properly initialized");
  }
  
  const exports = wasmModule.exports;
  
  // Look for the luxInfo function
  if (exports.luxInfo) {
    // If luxInfo is directly exported
    return exports.luxInfo(videoURL);
  }
  
  // If we need to use memory management
  if (exports.memory && exports.malloc && exports.free) {
    const encoder = new TextEncoder();
    const urlBytes = encoder.encode(videoURL);
    
    // Allocate memory
    const ptr = exports.malloc(urlBytes.length + 1);
    if (!ptr) {
      throw new Error("Failed to allocate memory");
    }
    
    // Copy the string to WASM memory
    const wasmMemory = new Uint8Array(exports.memory.buffer);
    wasmMemory.set(urlBytes, ptr);
    wasmMemory[ptr + urlBytes.length] = 0; // Null terminator
    
    // Call the function
    const resultPtr = exports.luxInfo ? exports.luxInfo(ptr) : 0;
    
    // Free memory
    exports.free(ptr);
    
    if (resultPtr === 0) {
      throw new Error("Go function returned null");
    }
    
    // Read the result
    let resultLength = 0;
    while (wasmMemory[resultPtr + resultLength] !== 0) {
      resultLength++;
    }
    
    const resultBytes = wasmMemory.slice(resultPtr, resultPtr + resultLength);
    const resultString = new TextDecoder().decode(resultBytes);
    
    // Free result memory
    exports.free(resultPtr);
    
    return resultString;
  }
  
  throw new Error("Could not find suitable Go function interface");
}

